/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Identifiers
 *   Functions: slot, trackId, mbid, sha, track, member, asset, imported
 *   Constants: albumId, otherAlbum, barcode, catalogNumber, applied, tagged, tagIdentifiers, full
 * Tests
 *   - an Album whose every member one import published and still holds captures the applied release and the shared tag identifiers
 *   - without provenance for every member there is no evidence
 *   - several imports that appended members keep the applied release only when all applied the same MusicBrainz release
 *   - each tag identifier counts only when every member carries it with one valid value; a gap or disagreement drops only that one
 * @end-catalog */

/**
 * The import evidence an existing-Album review captures, derived without a database from the members' Tracks and the imports that
 * published them: provenance, the applied MusicBrainz release, and the identifiers every member's staged tags share. All names and
 * identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { catalogReviewImportEvidenceOf, type CatalogReviewEvidenceImport, type CatalogReviewEvidenceMember } from '../../src/administration/catalog/adminCatalogReviewImportEvidence';

const albumId = '0000000000000000000000a1', otherAlbum = '0000000000000000000000a2';
const slot = (index: number) => `0000000b-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const trackId = (index: number) => `0000000000000000000b${String(index + 1).padStart(4, '0')}`;
const mbid = (index: number) => `0000000f-0000-4000-8000-${String(index).padStart(12, '0')}`;
const sha = (index: number) => String(index).repeat(64).slice(0, 64);
const barcode = '4006381333931', catalogNumber = 'SYN-0001', applied = mbid(501), tagged = mbid(502);
type Identifiers = { barcode?: string | null; catalogNumber?: string | null; musicBrainzReleaseId?: string | null };
const tagIdentifiers = { barcode, catalogNumber, musicBrainzReleaseId: tagged };

/** Member `index`'s Track as an import published it (FLAC), with `changes`. */
function track(index: number, changes: Record<string, unknown> = {}) {
    const key = `audio/${trackId(index)}/0000000000000000000f000${index + 1}`;
    return { _id: new ObjectId(trackId(index)), mediaType: 'audio', s3Key: key, contentType: 'audio/flac',
        mediaByteHash: { algorithm: 'sha256', value: sha(index + 1), byteLength: 1_000 + index, objectKey: key, etag: `"etag-${index}"`, versionId: null },
        mediaRepresentation: { objectKey: key, etag: `"etag-${index}"`, versionId: null, byteLength: 1_000 + index, durationMs: 200_000 }, ...changes };
}
const member = (index: number, changes: Record<string, unknown> = {}): CatalogReviewEvidenceMember => ({ slotId: slot(index), trackId: trackId(index), track: track(index, changes) });
/** Member `index`'s staged asset with version-2 tag identifiers (`identifiers`; `version: 1` stores legacy tags). */
const asset = (index: number, identifiers: Identifiers = tagIdentifiers, options: { state?: string; version?: 1 } = {}) => ({
    slotId: slot(index), state: options.state ?? 'deleted', sha256: sha(index + 1), byteLength: 1_000 + index,
    tags: options.version === 1 ? { title: 'Synthetic', artists: [] }
        : { version: 2, artists: [], albumArtists: [], flagged: [], identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null, ...identifiers } }
});
/** An import that published `members` (reused when listed in `reused`) of `album`, with a lookup application of `releaseId`. */
function imported(members: number[], options: { reused?: number[]; album?: string; state?: string; applied?: unknown; assets?: unknown[]; identifiers?: Identifiers } = {}): CatalogReviewEvidenceImport {
    return {
        publication: { state: options.state ?? 'complete', albumId: options.album ?? albumId,
            tracks: members.map(index => ({ slotId: slot(index), id: trackId(index), key: 'x', reused: (options.reused ?? []).includes(index) })) },
        assets: options.assets ?? members.map(index => asset(index, options.identifiers)),
        applied: options.applied === undefined ? { choice: 'preselected', candidateKey: `musicbrainz:${applied}`, releaseId: applied } : options.applied
    };
}
const full = { releaseId: applied, tagReleaseId: tagged, barcode, catalogNumber };

test('an Album whose every member one import published and still holds captures the applied release and the shared tag identifiers', () => {
    assert.deepEqual(catalogReviewImportEvidenceOf(albumId, [member(0), member(1)], [imported([0, 1])]), full);
    // A chosen candidate counts as a preselected one, and a ready asset as a cleaned-up one.
    assert.deepEqual(catalogReviewImportEvidenceOf(albumId, [member(0)], [imported([0], { applied: { choice: 'chosen', candidateKey: `musicbrainz:${applied}`, releaseId: applied },
        assets: [asset(0, tagIdentifiers, { state: 'ready' })] })]), full);
});

test('without provenance for every member there is no evidence', () => {
    const cases: [string, CatalogReviewEvidenceMember[], CatalogReviewEvidenceImport[]][] = [
        ['an Album without members', [], [imported([0])]],
        ['a member published only as reused', [member(0), member(1)], [imported([0, 1], { reused: [1] })]],
        ['a member uploaded through Content Manager (no import published it)', [member(0), member(1)], [imported([0])]],
        ['a mixed Album', [member(0), member(1), member(2)], [imported([0, 1])]],
        ['a member whose bytes local MP3 conversion replaced', [member(0), member(1, { contentType: 'audio/mpeg', s3Key: `audio/${trackId(1)}/0000000000000000000f0009`,
            mediaByteHash: { algorithm: 'sha256', value: sha(9), byteLength: 500, objectKey: `audio/${trackId(1)}/0000000000000000000f0009`, etag: '"converted"', versionId: null },
            mediaRepresentation: { objectKey: `audio/${trackId(1)}/0000000000000000000f0009`, etag: '"converted"', versionId: null, byteLength: 500 } })], [imported([0, 1])]],
        ['a failed asset', [member(0)], [imported([0], { assets: [asset(0, tagIdentifiers, { state: 'failed' })] })]],
        ['a missing asset', [member(0)], [imported([0], { assets: [] })]],
        ['two imports claiming one member', [member(0)], [imported([0]), imported([0])]],
        ['a publication not complete', [member(0)], [imported([0], { state: 'publishing' })]],
        ['a publication for another Album', [member(0)], [imported([0], { album: otherAlbum })]],
        ['no import at all', [member(0)], []]
    ];
    for (const [name, members, imports] of cases) assert.equal(catalogReviewImportEvidenceOf(albumId, members, imports), null, name);
    // `reused` must be stored as false: a missing value, or a malformed slot, is not proof.
    const unflagged = imported([0]);
    (unflagged.publication as { tracks: Record<string, unknown>[] }).tracks.forEach(entry => { delete entry.reused; });
    assert.equal(catalogReviewImportEvidenceOf(albumId, [member(0)], [unflagged]), null);
    const badSlot = imported([0]);
    (badSlot.publication as { tracks: Record<string, unknown>[] }).tracks[0].slotId = 'slot-one';
    assert.equal(catalogReviewImportEvidenceOf(albumId, [member(0)], [badSlot]), null);
    for (const malformed of [{ publication: null, assets: null, applied: null }, { publication: { state: 'complete', albumId, tracks: 'x' }, assets: 'x', applied: 'x' }]) {
        assert.equal(catalogReviewImportEvidenceOf(albumId, [member(0)], [malformed]), null);
    }
});

test('several imports that appended members keep the applied release only when all applied the same MusicBrainz release', () => {
    const members = [member(0), member(1), member(2)];
    // The second import appended member 2 and reused member 1, which the first import published.
    const first = imported([0, 1]), second = (applied?: unknown) => imported([1, 2], { reused: [1], applied, assets: [asset(2)] });
    assert.deepEqual(catalogReviewImportEvidenceOf(albumId, members, [first, second()]), full);
    for (const [name, other] of [['another release', { choice: 'preselected', candidateKey: `musicbrainz:${mbid(503)}`, releaseId: mbid(503) }],
        ['an iTunes-only application', { choice: 'chosen', candidateKey: 'itunes:123456', releaseId: '123456', source: 'itunes' }],
        ['none chosen', { choice: 'none', candidateKey: null, releaseId: null }], ['no lookup record', null]] as const) {
        assert.deepEqual(catalogReviewImportEvidenceOf(albumId, members, [first, second(other)]), { ...full, releaseId: null }, name);
    }
});

test('each tag identifier counts only when every member carries it with one valid value; a gap or disagreement drops only that one', () => {
    const evidence = (assets: unknown[], applied?: unknown) => catalogReviewImportEvidenceOf(albumId, [member(0), member(1)], [imported([0, 1], { assets, applied })]);
    assert.deepEqual(evidence([asset(0), asset(1, { ...tagIdentifiers, barcode: null })]), { ...full, barcode: null });
    assert.deepEqual(evidence([asset(0), asset(1, { ...tagIdentifiers, barcode: '5012345678900' })]), { ...full, barcode: null });
    assert.deepEqual(evidence([asset(0), asset(1, { ...tagIdentifiers, catalogNumber: 'SYN-0002' })]), { ...full, catalogNumber: null });
    assert.deepEqual(evidence([asset(0, { ...tagIdentifiers, musicBrainzReleaseId: mbid(7) }), asset(1)]), { ...full, tagReleaseId: null });
    // Invalid stored values are dropped: a wrong GTIN check digit, a malformed release ID, a link or a control character.
    const invalid = { barcode: '4006381333932', musicBrainzReleaseId: 'not-an-id', catalogNumber: 'https://example.test/x' };
    assert.deepEqual(evidence([asset(0, invalid), asset(1, invalid)]), { ...full, tagReleaseId: null, barcode: null, catalogNumber: null });
    assert.deepEqual(evidence([asset(0, { catalogNumber: 'SYN\u00070001' }), asset(1, { catalogNumber: 'SYN\u00070001' })]), { ...full, tagReleaseId: null, barcode: null, catalogNumber: null });
    // Version-1 tags give no tag identifier.
    assert.deepEqual(evidence([asset(0, tagIdentifiers, { version: 1 }), asset(1)]), { ...full, tagReleaseId: null, barcode: null, catalogNumber: null });
    // Provenance without any identifier is no evidence.
    assert.equal(evidence([asset(0, {}), asset(1, {})], null), null);
});
